sys_variable_value.value:
(function() {
    var planGr = new GlideRecord('x_1919740_dayone_0_onboarding_plan');
    planGr.initialize();
    planGr.setValue('employee_name', 'ATF Reopened Task');
    planGr.setValue('employee_id', 'ATF-008');
    planGr.setValue('state', 'active');
    planGr.setValue('readiness_threshold', 100);
    var planId = planGr.insert();

    var taskGr = new GlideRecord('x_1919740_dayone_0_onboarding_task');
    taskGr.initialize();
    taskGr.setValue('plan', planId);
    taskGr.setValue('task_name', 'Reopenable Task');
    taskGr.setValue('mandatory', true);
    taskGr.setValue('task_state', 'complete');
    taskGr.setValue('evidence_verified', true);
    taskGr.setValue('department', 'hr');
    var taskId = taskGr.insert();

    var engine = new DayOneReadinessEngine(planId);
    var scoreBefore = engine.calculateScore();
    if (scoreBefore !== 100) throw new Error('Score before reopen should be 100, got ' + scoreBefore);

    taskGr = new GlideRecord('x_1919740_dayone_0_onboarding_task');
    taskGr.get(taskId);
    taskGr.setValue('task_state', 'open');
    taskGr.setValue('evidence_verified', false);
    taskGr.update();

    var scoreAfter = engine.calculateScore();
    if (scoreAfter !== 0) throw new Error('Score after reopen should be 0, got ' + scoreAfter);
    gs.info('T-08 PASSED: Score recalculated after task reopened (100 -> 0)');
})();
